INSERT INTO `model` (`model_id`, `model_name`, `version`, `industry`, `remark`, `base_year`, `update_time`) VALUES
  ('hn_ct', '河南城投打分模型', '2026', NULL, '{"source": "河南城投打分模型.xlsx", "score_rule": "公司得分=Σ(打分项赋分×权重)+Σ排查项赋分；排查项 weight=0 直接加总", "grade_rule": "打分定级：得分落在 grade 表（左端点, 下一档左端点] 区间，左开右闭，首档[0,41]左闭，>100 出库", "grade_order": "R1+、R1、R2+、R2、R2-、R3+、R3、R3-、R4+、*R4+、R4、R5、出库（好→差，*为字符非通配符）", "expression_format": "db-formula-engine 包语法（2026-09-11 内核替换）：常量0｜字段直通 debt_negative_score｜case(条件,结果,...,else,兜底)｜数组分支 case(fid>={50,40,30},{5,4,3},else,0)（区间）与 case(fid={\\"唯一\\",\\"主要\\"},{5,20})（等值，键支持\\"A;B\\"多值）｜linear(fid,{x1,x2},{y1,y2}[,min,max]) 区间默认取 score_min/score_max 列｜max/min(子式...)｜round(子式,n) 不写则取 rounding 列｜字符串用双引号；x 已禁用（写指标自身 field_id）；期次引用 fid(YYYY)/fid(YYYY-MM-DD)/fid(Y)/fid(Y-n)；合计 sum(...)（旧名 SUM0）；除法敏感式 safe_divide(分子,分母,null)；裸四则缺值传播→待补", "year_convention": "同名字段不分年份，年份由 field_value.ann_dt 承载；X年平均类只录一行，ann_dt 取公式中最大年份；公式期次写法 fid(Y)/fid(Y-n) 相对 model.base_year，compute_fields 按落点年覆盖 base_year 计算", "indicator_value_rule": "indicator_value 实时计算不落库，得分与定级存快照 snapshots/", "formula_syntax": "pkg"}', 2025, '2026-09-12 22:00:00');

